def build_list(values, pos):
    if not values:
        return None
    nodes = [ListNode(v) for v in values]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]
    if pos != -1 and 0 <= pos < len(nodes):
        nodes[-1].next = nodes[pos]
    return nodes[0]

def generate(rng, n):
    values = [rng.randint(-1000, 1000) for _ in range(max(1, n))]
    pos = rng.choice([-1, rng.randint(0, len(values) - 1)])
    return [build_list(values, pos)]

def generate_worst(rng, n):
    values = [rng.randint(-1000, 1000) for _ in range(max(1, n))]
    return [build_list(values, -1)]

